// One item per site. radius_km: 1 to 50.
return [
  { json: { site: 'Istanbul office', lat: 41.0082, lon: 28.9784, radius_km: 5 } },
  { json: { site: 'Berlin warehouse', lat: 52.5200, lon: 13.4050, radius_km: 10 } },
  { json: { site: 'Paris hotel', lat: 48.8566, lon: 2.3522, radius_km: 3 } },
];

// One Slack-formatted digest per site. Items arrive in the same order as "Your sites".
const sites = $('Your sites').all();
const label = (slug) => (slug || '').replace(/-/g, ' ');

return $input.all().map((item, i) => {
  const site = sites[i].json;
  const events = item.json.structuredContent?.result?.events ?? [];
  const header = `*${site.site}* (${site.radius_km} km): ${events.length} event${events.length === 1 ? '' : 's'} in the last 24 hours`;
  const lines = events.slice(0, 10).map((e) => {
    const src = (e.sources ?? [])[0]?.url;
    const day = (e.occurred_at ?? '').slice(0, 10);
    return `• ${day} · _${label(e.category?.event)}_ · ${e.description}${src ? ` <${src}|source>` : ''}`;
  });
  if (events.length > 10) lines.push(`…and ${events.length - 10} more`);
  if (events.length === 0) lines.push('No events found in the news for this area. That does not prove it was calm.');
  return { json: { site: site.site, count: events.length, text: [header, ...lines].join('\n') } };
});
